/* Resolve an XL FB-input mux code to its source.
 * Returns 1 and fills fb/mc (1-based) and is_fb. */
int xl_imux2_lookup(const device_t *dev, int input_n, int code,
                    int *out_fb, int *out_mc, int *out_is_fb) {
    const xl_imux2_t *t = NULL; int n = 0, i;
    if (!dev || !dev->is_xl || input_n < 1 || input_n > 54) return 0;
    if      (!strncmp(dev->id, "XC9536XL",  8)) { t = &xl_imux2_xc9536xl[input_n-1][0]; n = 4; }
    else if (!strncmp(dev->id, "XC9572XL",  8)) { t = &xl_imux2_xc9572xl[input_n-1][0]; n = 8; }
    else if (!strncmp(dev->id, "XC95144XL", 9)) { t = &xl_imux2_xc95144xl[input_n-1][0]; n = 16; }
    else if (!strncmp(dev->id, "XC95288XL", 9)) { t = &xl_imux2_xc95288xl[input_n-1][0]; n = 27; }
    if (!t) return 0;
    for (i = 0; i < n; i++) {
        if (t[i].code == (unsigned char)code) {
            *out_fb    = t[i].mc / 18 + 1;
            *out_mc    = t[i].mc % 18 + 1;
            *out_is_fb = t[i].is_fb;
            return 1;
        }
    }
    return 0;
}


