/* A JED whose header names a device not in the table must not fall
 * through to fuse-count matching: XC95216-PQ160 (12 x 15552) has the same
 * total as XC95288XL-TQ144 (16 x 11664). Returns NULL so the caller
 * reports an unsupported device. */
/* True when the resolved row is a generic family row (id ends with '-'),
 * i.e. the JED does not name its package. Such a row carries a default
 * package's pin table (XC95108- uses PC84, XC9536- uses PC44, ...), so every
 * n_pNN name printed for such a file assumes a package; the output labels
 * it as such. */
int device_is_generic(const device_t *d) {
    if (!d || !d->id || !d->id[0]) return 0;
    size_t n = strlen(d->id);
    return d->id[n-1] == '-';
}

/* Every named package of a generic row's family, comma-joined into buf,
 * for the refusal message. Returns the count. dev may be a generic row
 * ("XC95108-") or a specific one (matched by its leading family token). */
int device_generic_candidates(const device_t *dev, char *buf, size_t buflen) {
    char devbase[32];
    const char *dash;
    size_t nb, used = 0;
    int i, n = 0;
    if (!dev || !dev->id || !buf || !buflen) return 0;
    dash = strchr(dev->id, '-');
    nb = dash ? (size_t)(dash - dev->id) : strlen(dev->id);
    if (nb >= sizeof devbase) nb = sizeof devbase - 1;
    memcpy(devbase, dev->id, nb);
    devbase[nb] = '\0';
    buf[0] = '\0';
    for (i = 0; ; i++) {
        const device_t *d = device_nth(i);
        const char *dd;
        if (!d) break;
        dd = strchr(d->id, '-');
        if (!dd || !dd[1]) continue;                 /* generic row itself */
        if (strncmp(d->id, devbase, nb) != 0 || d->id[nb] != '-') continue;
        {
            size_t plen = strlen(dd + 1);
            size_t sep = n ? 2 : 0;                   /* ", " */
            if (used + sep + plen + 1 > buflen) break;   /* never truncate silently mid-name */
            if (sep) { memcpy(buf + used, ", ", 2); used += 2; }
            memcpy(buf + used, dd + 1, plen); used += plen;
            buf[used] = '\0';
        }
        n++;
    }
    return n;
}

int device_named_but_unknown(const char *name) {
    /* True only when the header names a device family that has no row.
     *
     * Must not fire on a bare family name like "XC9536" (as some programmer
     * dumps write): device_find() cannot resolve those without a package,
     * but fuse-count detection resolves them.
     *
     * Compare only the leading token, up to the first '-': "XC95216" has no
     * row, "XC9536" has many. */
    if (!name || !name[0]) return 0;
    size_t n = 0;
    while (name[n] && name[n] != '-') n++;
    if (n == 0) return 0;
    for (const device_t *d = device_table; d->id; d++)
        if (strncasecmp(d->id, name, n) == 0 &&
            (d->id[n] == '-' || d->id[n] == '\0'))
            return 0;                 /* family is known */
    return 1;                         /* named, but no row for this family */
}

/* Local-feedback complement lookup. Returns the number of
 * destination-FB macrocells the vendor crossbar allows for this pair that
 * fc_table does not carry, and writes them to out[] (up to 3). Returns 0
 * when there is no data for this device (only XC95108 has it).
 * A caller may resolve by elimination only when this returns exactly 1. */
int fc_lfb_missing(const device_t *dev, int fb, int pair, int *out) {
    const signed char *e;
    int n, i;
    if (!dev || dev->is_xl || fb < 1 || fb > dev->n_fbs) return 0;
    if (pair < 0 || pair >= FC_PAIRS_PER_FB) return 0;
    if (strncmp(dev->id, "XC95108-", 8) != 0) return 0;
    if (dev->n_fbs != 6) return 0;
    e = fc_lfb_xc95108[fb-1][pair];
    n = e[0];
    if (n < 0 || n > 3) return 0;
    for (i = 0; i < n; i++) out[i] = e[1+i];
    return n;
}

const device_t *device_detect(int total_fuses) {
    /* Looked up by name, not by table position, so reordering the table
     * cannot change the result. */
    if (total_fuses == 18144) return device_find("XC9536-PC44");
    if (total_fuses == 41472) return device_find("XC9572-PQ100");

    /* Ambiguity guard, before the XL branch below.
     *
     * XC95216 (non-XL, 12 FBs x 15552) and XC95288XL (XL, 16 FBs x 11664)
     * have the same total fuse count, 186624: different family, layout
     * (FB-major vs band-interleaved) and IMUX width (36 vs 54). A nameless
     * file of that size is refused. */
    {
        const device_t *first = NULL;
        int distinct = 0;
        for (const device_t *d = device_table; d->id; d++) {
            if (!d->id[0] || d->n_fbs <= 0 || d->jed_fuses_per_fb <= 0) continue;
            if (d->n_fbs * d->jed_fuses_per_fb != total_fuses) continue;
            if (!first) { first = d; distinct = 1; continue; }
            {
                const char *da = strchr(first->id, '-');
                const char *db = strchr(d->id, '-');
                size_t la = da ? (size_t)(da - first->id) : strlen(first->id);
                size_t lb = db ? (size_t)(db - d->id)     : strlen(d->id);
                if (la != lb || strncmp(first->id, d->id, la) != 0) {
                    distinct = 2;
                    break;
                }
            }
        }
        if (distinct > 1) {
            fprintf(stderr,
                "device_detect: fuse count %d is AMBIGUOUS -- it matches more "
                "than one device:\n", total_fuses);
            for (const device_t *d = device_table; d->id; d++)
                if (d->id[0] && d->n_fbs > 0 && d->jed_fuses_per_fb > 0 &&
                    d->n_fbs * d->jed_fuses_per_fb == total_fuses)
                    fprintf(stderr, "    %-16s %-10s %2d FBs\n",
                            d->id, d->family, d->n_fbs);
            fprintf(stderr,
                "  Refusing to guess from fuse count alone. Name the part:\n"
                "    --device <DEVICE> --package <PACKAGE>\n");
            return NULL;
        }
    }

    if (total_fuses % XL_FUSES_PER_FB == 0) {
        int n = total_fuses / XL_FUSES_PER_FB;
        for (const device_t *d = device_table; d->id; d++)
            if (d->is_xl && d->n_fbs == n && d->mc_pin) return d;
        for (const device_t *d = device_table; d->id; d++)
            if (d->is_xl && d->n_fbs == n) return d;
    }
    /* Non-XL densities: XC95108 (69984), XC95144 (103680), XC95216
     * (186624), XC95288 (290304).
     *
     * Resolved from the table, preferring the generic family row (id ending
     * in '-'): a fuse count names the die, never the package. The generic
     * row carries a default pin table, so run_vhdl() refuses to emit a UCF
     * of guessed LOCs, while `decode` and `dump` -- which do not depend on
     * the package -- work normally. */
    {
        const device_t *hit = NULL;
        for (const device_t *d = device_table; d->id; d++) {
            if (!d->id[0] || d->n_fbs <= 0 || d->jed_fuses_per_fb <= 0) continue;
            if (d->n_fbs * d->jed_fuses_per_fb != total_fuses) continue;
            if (!hit) hit = d;
            if (d->id[strlen(d->id) - 1] == '-') { hit = d; break; }
        }
        if (hit) return hit;
    }

    fprintf(stderr, "device_detect: unknown fuse count %d\n"
                    "  known fuse counts:\n", total_fuses);
    {
        /* listed from the table itself */
        for (const device_t *d = device_table; d->id; d++) {
            size_t n;
            if (!d->id[0] || d->n_fbs <= 0 || d->jed_fuses_per_fb <= 0) continue;
            n = strlen(d->id);
            if (d->id[n - 1] != '-') continue;
            fprintf(stderr, "    %-8d %-10s %.*s\n",
                    d->n_fbs * d->jed_fuses_per_fb, d->family,
                    (int)(n - 1), d->id);
        }
    }
    return NULL;
}

/* Iterate the device table. Returns NULL past the end, so a caller can
 * walk i = 0,1,2,... until NULL. */
const device_t *device_nth(int i) {
    int n = 0;
    for (const device_t *d = device_table; d->id; d++, n++)
        if (n == i) return d;
    return NULL;
}

/* Device-vs-JED size guard.
 *
 * A device named on the command line must match the fuse count of the JED
 * loaded: a larger device would make the decoder read past the end of the
 * fuse buffer. A mismatch is refused. */
int device_fits_jed(const device_t *dev, unsigned long jed_fuses) {
    if (!dev || dev->n_fbs <= 0 || dev->jed_fuses_per_fb <= 0) return 1;
    return (unsigned long)dev->n_fbs * (unsigned long)dev->jed_fuses_per_fb
           == jed_fuses;
}

const device_t *device_find(const char *name) {
    for (const device_t *d = device_table; d->id; d++) {
        size_t idlen = strlen(d->id);
        if (!idlen || d->id[idlen-1] == '-') continue;
        if (strncasecmp(d->id, name, idlen) == 0 &&
            !isalnum((unsigned char)name[idlen])) return d;
    }
    for (const device_t *d = device_table; d->id; d++) {
        size_t idlen = strlen(d->id);
        if (!idlen || d->id[idlen-1] == '-') continue;
        const char *id_pkg = strrchr(d->id, '-');
        if (!id_pkg) continue;
        const char *nm_pkg = strrchr(name, '-');
        if (!nm_pkg) continue;
        if (strcasecmp(id_pkg, nm_pkg) != 0) continue;
        const char *id_dash = strchr(d->id, '-');
        const char *nm_dash = strchr(name, '-');
        if (!id_dash || !nm_dash) continue;
        if ((id_dash-d->id) != (nm_dash-name)) continue;
        if (strncasecmp(d->id, name, (size_t)(id_dash-d->id)) != 0) continue;
        return d;
    }
    for (const device_t *d = device_table; d->id; d++) {
        size_t idlen = strlen(d->id);
        if (!idlen || d->id[idlen-1] != '-') continue;
        if (strncasecmp(d->id, name, idlen) == 0) return d;
    }
    return NULL;
}

