void device_list(void) {
    printf("Known devices (QF = total JED fuse count):\n");
    printf("Status: this device's source-name table against the vendor's own .chp (from\n");
    printf("vendor data, not silicon): entries that agree / entries the .chp predicts.\n");
    printf("XL: the .chp <imux> table decode consults first; \"fallback table\" is the\n");
    printf("device_t imux_table used only when that lookup fails.\n");
    for (const device_t *d = device_table; d->id; d++) {
        if (!d->id[0]) break;
        if (d->id[strlen(d->id)-1] == '-') continue;
        const struct table_vs_chp *t = NULL;
        size_t k;
        for (k = 0; k < sizeof table_vs_chp / sizeof table_vs_chp[0]; k++)
            if (!strcmp(table_vs_chp[k].id, d->id)) t = &table_vs_chp[k];
        char st[160], ex[120];
        if (!t) {
            snprintf(st, sizeof st, "no measured table status");
        } else {
            int n = 0;
            ex[0] = 0;
            if (t->pred - t->agree)
                n += snprintf(ex + n, sizeof ex - n, "%s%d missing", n ? "; " : "",
                              t->pred - t->agree);
            if (t->not_in_chp)
                n += snprintf(ex + n, sizeof ex - n, "%s%d not in .chp", n ? "; " : "",
                              t->not_in_chp);
            if (t->is_xl) {
                n += snprintf(ex + n, sizeof ex - n, "%sfallback table %d/%d", n ? "; " : "",
                              t->fb_agree, t->fb_pred);
                if (t->fb_not_in_chp)
                    n += snprintf(ex + n, sizeof ex - n, ", %d not in .chp", t->fb_not_in_chp);
            }
            snprintf(st, sizeof st, "%s vs .chp %d/%d%s%s%s", t->is_xl ? "IMUX" : "FC",
                     t->agree, t->pred, ex[0] ? " (" : "", ex, ex[0] ? ")" : "");
        }
        int qf = d->n_fbs * d->jed_fuses_per_fb;
        printf("  %-26s  %-12s  %-3s  n_fbs=%-2d  QF=%-7d  %s\n",
               d->id, d->family, d->is_xl ? "XL" : "",
               d->n_fbs, qf, st);
    }
}

/* ===================================================================
 * NOTE ON BGA PIN ENCODING
 * Ball designators (e.g. "B7", "G3") are encoded as:
 *   1000 + row*100 + col, row A=1 ... Z=26, AA..AF = 27..32
 * So A1=1101, B7=1207, G7=1707.
 * Signal names: ball_B7, ball_G3, etc. (bga_pin_name() in decode.h)
 * ================================================================= */
